using namespace std;using U=uint32_t;using L=uint64_t;const U NIL=UINT32_MAX;template<class T>T rd(ifstream&f){T x;f.read((char*)&x,sizeof x);assert(f);return x;}template<class T>void wr(ofstream&f,T x){f.write((char*)&x,sizeof x);}int main(int argc,char**argv){rlimit lim{6ULL<<30,6ULL<<30};assert(!setrlimit(RLIMIT_AS,&lim));assert(argc==2);string pre=argv[1];ifstream sf(pre+".states",ios::binary);U n=rd<U>(sf),N=rd<U>(sf);assert(n==12&&N==13899559);vector<L>S(N);vector<int8_t>M(N),A(N);sf.read((char*)S.data(),8ULL*N);sf.read((char*)M.data(),N);sf.read((char*)A.data(),N);assert(sf);vector<vector<U>>D(N),R(N);vector<U>ind(N),samein(N),sameout(N),stamp(N);vector<unsigned char>live(N,1);L E=0,reverse=0;ifstream mf(pre+".matrix",ios::binary);assert(rd<U>(mf)==N);for(U a=0;a<N;a++){U z=rd<U>(mf);D[a].resize(z);mf.read((char*)D[a].data(),4ULL*z);assert(mf);for(U b:D[a]){assert(M[a]==M[b]+1&&A[a]>=A[b]);ind[b]++;R[b].push_back(a);if(A[a]==A[b]){samein[b]++;sameout[a]++;}}E+=z;}reverse=E;L maxedges=E;deque<pair<U,U>>Q0,Q1;U tick=0;auto valid=[&](U a,U b){return live[a]&&live[b]&&binary_search(D[a].begin(),D[a].end(),b);};auto incoming=[&](U b,bool eq){vector<U>v;tick++;for(U a:R[b])if(stamp[a]!=tick&&valid(a,b)&&(!eq||A[a]==A[b])){stamp[a]=tick;v.push_back(a);}assert(v.size()==(eq?samein[b]:ind[b]));return v;};auto pushsource=[&](U a){if(!live[a]||!sameout[a])return;if(sameout[a]==1){U b=NIL;for(U x:D[a])if(A[x]==A[a]){b=x;break;}assert(b!=NIL);(D[a].size()==1||ind[b]==1?Q0:Q1).emplace_back(a,b);}};for(U a=0;a<N;a++)pushsource(a);for(U b=0;b<N;b++)if(samein[b]==1){auto v=incoming(b,true);(ind[b]==1||D[v[0]].size()==1?Q0:Q1).emplace_back(v[0],b);}
vector<U>changed;auto alter=[&](U a,vector<U>&nw){assert(is_sorted(nw.begin(),nw.end()));for(U b:nw)assert(live[b]&&M[a]==M[b]+1&&A[a]>=A[b]);auto&old=D[a];size_t i=0,j=0;while(i<old.size()||j<nw.size()){if(j==nw.size()||(i<old.size()&&old[i]<nw[j])){U b=old[i++];E--;if(live[b]){assert(ind[b]);ind[b]--;if(A[a]==A[b]){assert(samein[b]);samein[b]--;}changed.push_back(b);}}else if(i==old.size()||nw[j]<old[i]){U b=nw[j++];E++;ind[b]++;if(A[a]==A[b])samein[b]++;R[b].push_back(a);reverse++;changed.push_back(b);}else{i++;j++;}}D[a].swap(nw);sameout[a]=0;for(U b:D[a])sameout[a]+=A[a]==A[b];pushsource(a);};
ofstream tr(pre+".filtered-elimination",ios::binary);wr(tr,N);L done=0,nonfree=0,maxcost=0;map<pair<int,int>,L>pairs;
while(true){U a=NIL,b=NIL;auto pick=[&](auto&Q,bool hard){while(!Q.empty()){auto [x,y]=Q.front();Q.pop_front();if(!valid(x,y)||A[x]!=A[y])continue;if(hard){if(D[x].size()!=1&&ind[y]!=1)continue;}else{if(sameout[x]!=1&&samein[y]!=1)continue;if((D[x].size()-1ULL)*(ind[y]-1ULL)>1000)continue;}a=x;b=y;return true;}return false;};if(!pick(Q0,true))pick(Q1,false);if(a==NIL){L cost=UINT64_MAX;for(U x=0;x<N;x++)if(live[x]&&sameout[x])for(U y:D[x])if(A[x]==A[y]){L c=(D[x].size()-1ULL)*(ind[y]-1ULL);if(c<cost){cost=c;a=x;b=y;}}if(a==NIL)break;maxcost=max(maxcost,cost);nonfree++;}assert(valid(a,b)&&A[a]==A[b]&&M[a]==M[b]+1);vector<U>da=D[a],ib=incoming(b,false),ia=incoming(a,false);live[a]=live[b]=0;changed.clear();for(U c:ib)if(live[c]){vector<U>nw;set_symmetric_difference(D[c].begin(),D[c].end(),da.begin(),da.end(),back_inserter(nw));nw.erase(remove_if(nw.begin(),nw.end(),[&](U v){return !live[v];}),nw.end());alter(c,nw);}for(U c:ia)if(live[c]){vector<U>nw=D[c];auto it=lower_bound(nw.begin(),nw.end(),a);if(it!=nw.end()&&*it==a)nw.erase(it);alter(c,nw);}vector<U>empty;alter(a,empty);empty.clear();alter(b,empty);ind[a]=ind[b]=samein[a]=samein[b]=sameout[a]=sameout[b]=0;for(U y:changed)if(live[y]&&samein[y]==1){auto v=incoming(y,true);(ind[y]==1||D[v[0]].size()==1?Q0:Q1).emplace_back(v[0],y);}wr(tr,a);wr(tr,b);pairs[{M[a],A[a]}]++;done++;maxedges=max(maxedges,E);if(done%50000==0){tr.flush();cerr<<"sameA pairs="<<done<<" edges="<<E<<" reverse="<<reverse<<" queues="<<Q0.size()<<","<<Q1.size()<<"\n";}if(E>250000000ULL||reverse>450000000ULL||Q0.size()+Q1.size()>50000000ULL)throw runtime_error("sparse fill cap reached; count checkpoint and finite contraction prefix preserved");}
tr.close();cerr<<"sameA complete pairs="<<done<<" edges="<<E<<" nonfree="<<nonfree<<"\n";
vector<U>V;for(U i=0;i<N;i++)if(live[i]&&(M[i]==0||!D[i].empty()||ind[i]>0))V.push_back(i);sort(V.begin(),V.end(),[&](U x,U y){if(A[x]!=A[y])return A[x]<A[y];if(M[x]!=M[y])return M[x]<M[y];return x<y;});U K=V.size();assert(K<200000);vector<int>loc(N,-1);for(U i=0;i<K;i++)loc[V[i]]=i;vector<vector<U>>C(K);ofstream rf(pre+".residual",ios::binary);wr(rf,K);for(U i=0;i<K;i++){U a=V[i];wr(rf,a);wr(rf,M[a]);wr(rf,A[a]);for(U b:D[a]){assert(live[b]&&loc[b]>=0&&A[a]>A[b]);C[i].push_back(loc[b]);}sort(C[i].begin(),C[i].end());wr(rf,(U)C[i].size());rf.write((char*)C[i].data(),4ULL*C[i].size());}rf.close();cerr<<"filtered residual vertices="<<K<<"\n";
vector<vector<U>>basis(K);vector<int>pivotcol(K,-1);vector<unsigned char>birth(K,0);ofstream pr(pre+".persistence-reductions",ios::binary);wr(pr,K);L xors=0;for(U i=0;i<K;i++){vector<U>v=C[i],ops;while(!v.empty()){U p=v.back();assert(p<i);if(pivotcol[p]<0){pivotcol[p]=i;basis[p]=v;break;}U q=pivotcol[p];ops.push_back(q);vector<U>w;set_symmetric_difference(v.begin(),v.end(),basis[p].begin(),basis[p].end(),back_inserter(w));v.swap(w);xors++;}if(v.empty())birth[i]=1;wr(pr,(U)ops.size());pr.write((char*)ops.data(),4ULL*ops.size());}pr.close();vector<U>infinite;for(U i=0;i<K;i++)if(M[V[i]]==0&&birth[i]&&pivotcol[i]<0)infinite.push_back(i);assert(infinite.size()==1);int tau=A[V[infinite[0]]];assert(tau==0);
ofstream out(pre+".tau.json");out<<"{\"address_space_cap_bytes\":6442450944,\"three_grade_states\":"<<N<<",\"same_A_cancellations\":"<<done<<",\"maximum_live_edges\":"<<maxedges<<",\"nonfree_same_A_choices\":"<<nonfree<<",\"maximum_nonfree_cost\":"<<maxcost<<",\"residual_vertices\":"<<K<<",\"persistence_column_xors\":"<<xors<<",\"infinite_M0_bars\":[{\"birth_A\":"<<tau<<",\"residual_index\":"<<infinite[0]<<",\"original_state_index\":"<<V[infinite[0]]<<"}],\"tau\":0,\"cancelled_bigraded_pairs\":[";bool first=true;for(auto [g,z]:pairs){if(!first)out<<",";first=false;out<<"["<<g.first<<","<<g.second<<","<<z<<"]";}out<<"]}\n";cerr<<"PERSISTENCE COMPLETE tau="<<tau<<" unique infinite M0 bar\n";
}
